    name: 'str',
    module: 'builtins',
    executor: (args) => String(args[0])
  });

  registry.register({
    name: 'int',
    module: 'builtins',
    executor: (args) => parseInt(String(args[0]))
  });

  registry.register({
    name: 'float',
    module: 'builtins',
    executor: (args) => parseFloat(String(args[0]))
  });

  registry.register({
    name: 'bool',
    module: 'builtins',
    executor: (args) => Boolean(args[0])
  });

  registry.register({
    name: 'typeof',
    module: 'builtins',
    executor: (args) => typeof args[0]
  });

  // ────────────────────────────────────────────────────────────
  // Phase A-1b: 핵심 컬렉션/문자열 함수
  // ────────────────────────────────────────────────────────────

  registry.register({
    name: 'length',
    module: 'builtins',
    executor: (args) => {
      const obj = args[0];
      if (Array.isArray(obj)) return obj.length;
      if (typeof obj === 'string') return obj.length;
      if (obj instanceof Map) return obj.size;
      if (obj instanceof Set) return obj.size;
      return 0;
    }
  });

  registry.register({
    name: 'len',
    module: 'builtins',
    executor: (args) => {
      const obj = args[0];
      if (Array.isArray(obj)) return obj.length;
      if (typeof obj === 'string') return obj.length;
      if (obj instanceof Map) return obj.size;
      return 0;
    }
  });

  registry.register({
    name: 'push',
    module: 'builtins',
    paramCount: 2,
    executor: (args) => {
      const arr = args[0];
      if (Array.isArray(arr)) { arr.push(args[1]); return arr; }
      return arr;
    }
  });

  registry.register({
    name: 'pop',
    module: 'builtins',
    executor: (args) => {
      const arr = args[0];
      if (Array.isArray(arr)) return arr.pop();
      return null;
    }
