cat > /tmp/extract_stdlib.js << 'EOF'
const fs = require('fs');
const path = require('path');

const stdlibDir = '/data/data/com.termux/files/home/v2-archive/freelang-v2/src';
const files = fs.readdirSync(stdlibDir).filter(f => f.startsWith('stdlib') && f.endsWith('.ts'));

const functions = {};

files.forEach(file => {
  const content = fs.readFileSync(path.join(stdlibDir, file), 'utf-8');

  // Extract registry.register({ name: '...', ...})
  const matches = content.match(/registry\.register\(\s*\{\s*name:\s*['"`]([^'"`]+)['"`]/g) || [];

  matches.forEach(m => {
    const name = m.match(/name:\s*['"`]([^'"`]+)['"`]/)[1];
    if (!functions[name]) {
      functions[name] = { file, count: 0 };
    }
    functions[name].count++;
  });
});

console.log('총 함수 개수: ' + Object.keys(functions).length);
console.log('\n함수 목록 (모듈별):');

const byModule = {};
Object.entries(functions).forEach(([name, info]) => {
  const module = info.file.replace('stdlib-', '').replace('.ts', '');
  if (!byModule[module]) byModule[module] = [];
  byModule[module].push(name);
});

Object.entries(byModule).forEach(([module, funcs]) => {
  console.log(`\n## ${module} (${funcs.length})`);
  console.log(funcs.slice(0, 5).join(', ') + (funcs.length > 5 ? ', ...' : ''));
});
EOF
