  tokenize(): Token[] {
    const tokens: Token[] = [];

    while (this.position < this.source.length) {
      this.skipWhitespace();

      if (this.position >= this.source.length) break;

      const ch = this.source[this.position];

      // 숫자
      if (this.isDigit(ch)) {
        tokens.push(this.readNumber());
      }
      // 식별자/키워드
      else if (this.isLetter(ch)) {
        tokens.push(this.readIdentifier());
