      // 연산자
      else if (ch === '+') {
        tokens.push({ type: 'PLUS', value: '+' });
        this.position++;
      } else if (ch === '-') {
        tokens.push({ type: 'MINUS', value: '-' });
        this.position++;
      } else if (ch === '*') {
        tokens.push({ type: 'MUL', value: '*' });
        this.position++;
      } else if (ch === '/') {
        tokens.push({ type: 'DIV', value: '/' });
        this.position++;
      } else if (ch === '=') {
        tokens.push({ type: 'ASSIGN', value: '=' });
        this.position++;
      } else if (ch === '(') {
        tokens.push({ type: 'LPAREN', value: '(' });
        this.position++;
      } else if (ch === ')') {
        tokens.push({ type: 'RPAREN', value: ')' });
